import { Buffer32 } from '@aztec/foundation/buffer';
import { arraySerializedSizeOfNonEmpty } from '@aztec/foundation/collection';
import { Fr } from '@aztec/foundation/fields';
import { BufferReader, serializeArrayOfBufferableToVector, serializeToBuffer } from '@aztec/foundation/serialize';
import { z } from 'zod';
import { PrivateKernelTailCircuitPublicInputs } from '../kernel/private_kernel_tail_circuit_public_inputs.js';
import { ContractClassLog } from '../logs/contract_class_log.js';
import { Gossipable } from '../p2p/gossipable.js';
import { TopicType, createTopicString } from '../p2p/topic_type.js';
import { ClientIvcProof } from '../proofs/client_ivc_proof.js';
import { HashedValues } from './hashed_values.js';
import { PublicCallRequestWithCalldata } from './public_call_request_with_calldata.js';
import { TxHash } from './tx_hash.js';
/**
 * The interface of an L2 transaction.
 */ export class Tx extends Gossipable {
    data;
    clientIvcProof;
    contractClassLogs;
    publicFunctionCalldata;
    static p2pTopic;
    // For memoization
    txHash;
    calldataMap;
    constructor(/**
     * Output of the private kernel circuit for this tx.
     */ data, /**
     * Proof from the private kernel circuit.
     * TODO(#7368): This client IVC object currently contains various VKs that will eventually be more like static data.
     */ clientIvcProof, /**
     * Contract class logs generated by the tx.
     */ contractClassLogs, /**
     * An array of calldata for the enqueued public function calls and the teardown function call.
     */ publicFunctionCalldata){
        super(), this.data = data, this.clientIvcProof = clientIvcProof, this.contractClassLogs = contractClassLogs, this.publicFunctionCalldata = publicFunctionCalldata;
    }
    // Gossipable method
    static{
        this.p2pTopic = createTopicString(TopicType.tx);
    }
    // Gossipable method
    async p2pMessageIdentifier() {
        return new Buffer32((await this.getTxHash()).toBuffer());
    }
    hasPublicCalls() {
        return this.numberOfPublicCalls() > 0;
    }
    numberOfPublicCalls() {
        return this.data.numberOfPublicCallRequests();
    }
    getNonRevertiblePublicCallRequestsWithCalldata() {
        return this.data.getNonRevertiblePublicCallRequests().map((r)=>this.#combinePublicCallRequestWithCallData(r));
    }
    getRevertiblePublicCallRequestsWithCalldata() {
        return this.data.getRevertiblePublicCallRequests().map((r)=>this.#combinePublicCallRequestWithCallData(r));
    }
    getTeardownPublicCallRequestWithCalldata() {
        const request = this.data.getTeardownPublicCallRequest();
        return request ? this.#combinePublicCallRequestWithCallData(request) : undefined;
    }
    getPublicCallRequestsWithCalldata() {
        const teardown = this.data.getTeardownPublicCallRequest();
        const callRequests = [
            ...this.data.getNonRevertiblePublicCallRequests(),
            ...this.data.getRevertiblePublicCallRequests(),
            ...teardown ? [
                teardown
            ] : []
        ];
        return callRequests.map((r)=>this.#combinePublicCallRequestWithCallData(r));
    }
    getTotalPublicCalldataCount() {
        return this.publicFunctionCalldata.reduce((accum, cd)=>accum + cd.values.length, 0);
    }
    getGasSettings() {
        return this.data.constants.txContext.gasSettings;
    }
    /**
   * Deserializes the Tx object from a Buffer.
   * @param buffer - Buffer or BufferReader object to deserialize.
   * @returns An instance of Tx.
   */ static fromBuffer(buffer) {
        const reader = BufferReader.asReader(buffer);
        return new Tx(reader.readObject(PrivateKernelTailCircuitPublicInputs), reader.readObject(ClientIvcProof), reader.readVectorUint8Prefix(ContractClassLog), reader.readVectorUint8Prefix(HashedValues));
    }
    /**
   * Serializes the Tx object into a Buffer.
   * @returns Buffer representation of the Tx object.
   */ toBuffer() {
        return serializeToBuffer([
            this.data,
            this.clientIvcProof,
            serializeArrayOfBufferableToVector(this.contractClassLogs, 1),
            serializeArrayOfBufferableToVector(this.publicFunctionCalldata, 1)
        ]);
    }
    static get schema() {
        return z.object({
            data: PrivateKernelTailCircuitPublicInputs.schema,
            clientIvcProof: ClientIvcProof.schema,
            contractClassLogs: z.array(ContractClassLog.schema),
            publicFunctionCalldata: z.array(HashedValues.schema)
        }).transform(Tx.from);
    }
    static from(fields) {
        return new Tx(fields.data, fields.clientIvcProof, fields.contractClassLogs, fields.publicFunctionCalldata);
    }
    /**
   * Gets public logs emitted by this tx.
   * @param logsSource - An instance of `L2LogsSource` which can be used to obtain the logs.
   * @returns The requested logs.
   */ async getPublicLogs(logsSource) {
        return logsSource.getPublicLogs({
            txHash: await this.getTxHash()
        });
    }
    /**
   * Gets either revertible or non revertible contract class logs emitted by this tx.
   * @param revertible - true for revertible only logs, false for non reverible only logs.
   * @returns The requested logs.
   */ async getSplitContractClassLogs(revertible, silo = false) {
        // Should only be called on txs with public calls
        if (!this.data.forPublic) {
            return [];
        }
        const contractClassLogsHashes = revertible ? this.data.forPublic.revertibleAccumulatedData.contractClassLogsHashes.filter((h)=>!h.isEmpty()) : this.data.forPublic.nonRevertibleAccumulatedData.contractClassLogsHashes.filter((h)=>!h.isEmpty());
        return await this.filterContractClassLogs(contractClassLogsHashes, silo);
    }
    /**
   * Filters contract class logs emitted by this tx.
   * @param logHashes - logs to keep represented by their hashes.
   * @param silo - whether to silo the logs before returning them.
   * @returns The requested logs.
   */ async filterContractClassLogs(logHashes, silo = false) {
        const contractClassLogs = [];
        for (const log of this.contractClassLogs){
            const hashedLog = await log.hash();
            const logHash = logHashes.find((hash)=>hash.value.equals(hashedLog) && hash.contractAddress.equals(log.contractAddress));
            if (logHash) {
                contractClassLogs.push(silo ? await log.silo() : log);
            }
        }
        return contractClassLogs;
    }
    /**
   * Computes (if necessary) & return transaction hash.
   * @returns The hash of the public inputs of the private kernel tail circuit.
   */ async getTxHash(forceRecompute = false) {
        if (!this.txHash || forceRecompute) {
            const hash = this.data.forPublic ? await this.data.toPrivateToPublicKernelCircuitPublicInputs().hash() : await this.data.toPrivateToRollupKernelCircuitPublicInputs().hash();
            this.txHash = new TxHash(hash);
        }
        return this.txHash;
    }
    /**
   * Allows setting the hash of the Tx.
   * Use this when you want to skip computing it from the original data.
   * Don't set a Tx hash received from an untrusted source.
   * @param hash - The hash to set.
   */ setTxHash(hash) {
        this.txHash = hash;
    }
    getCalldataMap() {
        if (!this.calldataMap) {
            const calldataMap = new Map();
            this.publicFunctionCalldata.forEach((cd)=>calldataMap.set(cd.hash.toString(), cd.values));
            this.calldataMap = calldataMap;
        }
        return this.calldataMap;
    }
    /** Returns stats about this tx. */ async getStats() {
        return {
            txHash: (await this.getTxHash()).toString(),
            noteHashCount: this.data.getNonEmptyNoteHashes().length,
            nullifierCount: this.data.getNonEmptyNullifiers().length,
            privateLogCount: this.data.getNonEmptyPrivateLogs().length,
            classRegisteredCount: this.data.getNonEmptyContractClassLogsHashes().length,
            contractClassLogSize: this.data.getEmittedContractClassLogsLength(),
            proofSize: this.clientIvcProof.clientIvcProofBuffer.length,
            size: this.toBuffer().length,
            feePaymentMethod: // needsSetup? then we pay through a fee payment contract
            this.data.forPublic?.needsSetup ? 'fpc' : 'fee_juice'
        };
    }
    getSize() {
        return this.data.getSize() + this.clientIvcProof.clientIvcProofBuffer.length + arraySerializedSizeOfNonEmpty(this.contractClassLogs) + this.publicFunctionCalldata.reduce((accum, cd)=>accum + cd.getSize(), 0);
    }
    /**
   * Estimates the tx size based on its private effects. Note that the actual size of the tx
   * after processing will probably be larger, as public execution would generate more data.
   */ getEstimatedPrivateTxEffectsSize() {
        return this.data.getNonEmptyNoteHashes().length * Fr.SIZE_IN_BYTES + this.data.getNonEmptyNullifiers().length * Fr.SIZE_IN_BYTES + this.data.getEmittedPrivateLogsLength() * Fr.SIZE_IN_BYTES + this.data.getEmittedContractClassLogsLength() * Fr.SIZE_IN_BYTES;
    }
    /**
   * Convenience function to get a hash out of a tx or a tx-like.
   * @param tx - Tx-like object.
   * @returns - The hash.
   */ static async getHash(tx) {
        return hasHash(tx) ? tx.hash : await tx.getTxHash();
    }
    /**
   * Convenience function to get array of hashes for an array of txs.
   * @param txs - The txs to get the hashes from.
   * @returns The corresponding array of hashes.
   */ static async getHashes(txs) {
        return await Promise.all(txs.map(Tx.getHash));
    }
    /**
   * Clones a tx, making a deep copy of all fields.
   * @param tx - The transaction to be cloned.
   * @returns The cloned transaction.
   */ static clone(tx) {
        const publicInputs = PrivateKernelTailCircuitPublicInputs.fromBuffer(tx.data.toBuffer());
        const clientIvcProof = ClientIvcProof.fromBuffer(tx.clientIvcProof.toBuffer());
        const contractClassLogs = tx.contractClassLogs.map((x)=>ContractClassLog.fromBuffer(x.toBuffer()));
        const publicFunctionCalldata = tx.publicFunctionCalldata.map((cd)=>HashedValues.fromBuffer(cd.toBuffer()));
        const clonedTx = new Tx(publicInputs, clientIvcProof, contractClassLogs, publicFunctionCalldata);
        if (tx.txHash) {
            clonedTx.setTxHash(TxHash.fromBuffer(tx.txHash.toBuffer()));
        }
        return clonedTx;
    }
    /**
   * Creates a random tx.
   * @param randomProof - Whether to create a random proof - this will be random bytes of the full size.
   * @returns A random tx.
   */ static async random(randomProof = false) {
        return new Tx(PrivateKernelTailCircuitPublicInputs.emptyWithNullifier(), randomProof ? ClientIvcProof.random() : ClientIvcProof.empty(), [
            await ContractClassLog.random()
        ], [
            HashedValues.random()
        ]);
    }
    /**
   * Filters out logs from functions that are not present in the provided kernel output.
   *
   * The purpose of this is to remove logs that got dropped due to a revert,
   * in which case, we only have the kernel's hashes to go on, as opposed to
   * this grouping by function maintained in this class.
   *
   * The logic therefore is to drop all FunctionLogs if any constituent hash
   * does not appear in the provided hashes: it is impossible for part of a
   * function to revert.
   *
   * @param logHashes the individual log hashes we want to keep
   * @param out the output to put passing logs in, to keep this function abstract
   */ async filterRevertedLogs() {
        this.contractClassLogs = await this.getSplitContractClassLogs(false);
    }
    #combinePublicCallRequestWithCallData(request) {
        const calldataMap = this.getCalldataMap();
        // Assume empty calldata if nothing is given for the hash.
        // The verification of calldata vs hash should be handled outside of this class.
        const calldata = calldataMap.get(request.calldataHash.toString()) ?? [];
        return new PublicCallRequestWithCalldata(request, calldata);
    }
}
function hasHash(tx) {
    return tx.hash !== undefined;
}
